import java.util.ArrayList;
import java.util.List;

public class Solution {
    public double[] averageOfLevels(TreeNode root) {
        List<List<Double>> levels = new ArrayList<>();
        List<Integer> counts = new ArrayList<>();

        // Perform level order traversal to calculate averages
        levelOrderTraversal(root, levels, counts);

        double[] result = new double[levels.size()];
        for (int i = 0; i < levels.size(); i++) {
            double sum = 0;
            for (double value : levels.get(i)) {
                sum += value;
            }
            result[i] = sum / counts.get(i);
        }

        return result;
    }

    private void levelOrderTraversal(TreeNode root, List<List<Double>> levels, List<Integer> counts) {
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Double> currentLevel = new ArrayList<>();
            int count = 0;

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                currentLevel.add((double) node.val);
                count++;

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            levels.add(currentLevel);
            counts.add(count);
        }
    }
}

