    void flatten(TreeNode* root) {
        if (!root) return;

        // Flatten the left subtree
        flatten(root->left);

        // Store the right subtree
        TreeNode* right = root->right;

        // Make the left subtree the new right subtree
        root->right = root->left;
        root->left = NULL;

