public class Solution {
    public List<Integer> boundaryOfBinaryTree(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) return result;

        // Add the left boundary nodes
        TreeNode current = root.left;
        while (current != null) {
            if (!isLeaf(current)) result.add(current.val);
            if (current.left != null) current = current.left;
            else current = current.right;
        }

        // Add the leaf nodes
        addLeaves(result, root);

        // Add the right boundary nodes in reverse order
        Stack<Integer> stack = new Stack<>();
        current = root.right;
        while (current != null) {
            if (!isLeaf(current)) stack.push(current.val);
            if (current.right != null) current = current.right;
            else current = current.left;
        }
        while (!stack.isEmpty()) {
            result.add(stack.pop());
        }

        return result;
    }

    private void addLeaves(List<Integer> result, TreeNode root) {
        if (isLeaf(root)) {
            result.add(root.val);
            return;
        }
        if (root.left != null) addLeaves(result, root.left);
        if (root.right != null) addLeaves(result, root.right);
    }

    private boolean isLeaf(TreeNode node) {
        return node.left == null && node.right == null;
    }
}

