        if (root == null) return new ArrayList<>();

        HashMap<Integer, List<Integer>> columnTable = new HashMap<>();
        Queue<Pair<TreeNode, Integer>> q = new LinkedList<>();
        q.offer(new Pair<>(root, 0));

        while (!q.isEmpty()) {
            int size = q.size();
            HashMap<Integer, List<Integer>> levelTable = new HashMap<>();

            for (int i = 0; i < size; i++) {
                TreeNode curNode = q.peek().getKey();
                int column = q.peek().getValue();
                q.poll();

                if (curNode != null) {
                    levelTable.putIfAbsent(column, new ArrayList<>());
                    levelTable.get(column).add(curNode.val);
                    q.offer(new Pair<>(curNode.left, column - 1));
                    q.offer(new Pair<>(curNode.right, column + 1));
                }
            }

            for (Map.Entry<Integer, List<Integer>> entry : levelTable.entrySet()) {
                List<Integer> values = entry.getValue();
                Collections.sort(values);
                columnTable.putIfAbsent(entry.getKey(), new ArrayList<>());
                columnTable.get(entry.getKey()).addAll(values);
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i <= columnTable.keySet().stream().max(Integer::compare).get(); i++) {
            if (columnTable.containsKey(i)) {
                result.addAll(columnTable.get(i));
            }
        }

        return result;
    }
}

