// Function to calculate the minimum number of steps required to make two strings anagrams
int minSteps(string s, string t) {
    vector<int> countS(26, 0);
    vector<int> countT(26, 0);
    int steps = 0;

    // Count the frequency of each character in both strings
    for (char c : s) countS[c - 'a']++;
    for (char c : t) countT[c - 'a']++;

    // Calculate the total number of steps required
    for (int i = 0; i < 26; i++) {
        steps += abs(countS[i] - countT[i]);
    }

    // Return half of the total steps, as each step involves swapping characters between the two strings
    return steps / 2;
}

// New function to calculate the minimum number of swaps required to make a binary tree symmetric
int minSwaps(TreeNode* root) {
    // Base case: if the tree is empty or has only one node, no swaps are needed
    if (!root || !root->left && !root->right) return 0;

    // Recursively calculate the minimum swaps required for the left and right subtrees
    int leftSwaps = minSwaps(root->left);
    int rightSwaps = minSwaps(root->right);

    // If the current node is not symmetric, swap its children and increment the swap count
    if (root->left->val != root->right->val) {
        swap(root->left, root->right);
        return leftSwaps + rightSwaps + 1;
    }

    // Otherwise, return the sum of the swaps from the left and right subtrees
    return leftSwaps + rightSwaps;
}

